285|/// One attempt of one reviewer (DESIGN §4).
286|pub trait Engine {
287|    /// The engine's capabilities.
288|    fn capabilities(&self) -> Capabilities;
289|
290|    /// The exact argv the plugin builds for `request` (subprocess engines only).
291|    fn plan(&self, request: &Request) -> Result<Argv, EngineError>;
292|
293|    /// Run one turn. Implemented in M2b (subprocess launch, event reader, reply
294|    /// ingestion, format repair). Signature only.
295|    fn run(&self, request: &Request) -> Result<Reply, EngineError>;
296|
297|    /// Continue a conversation with a follow-up prompt, where supported (codex/agy/muse
298|    /// resume; `http` replay). Implemented in M2b. Signature only.
299|    fn continue_turn(
300|        &self,
301|        conversation: &ConversationId,
302|        prompt: &str,
303|    ) -> Result<Reply, EngineError>;
304|}
