340|            .write(true)
341|            .create(true)
342|            .truncate(false)
343|            .open(&path)?;
344|        let bytes = record.to_bytes().map_err(map_err)?;
345|        file.set_len(0)?;
346|        file.write_all(&bytes)?;
347|        file.flush()?;
